def chamados_now_iso():
    return datetime.now().astimezone().isoformat()


def _json_lista(valor):
    return valor if isinstance(valor, list) else []


def _data_ou_none(valor):
    valor = str(valor or "").strip()
    if not valor:
        return None
    try:
        return datetime.strptime(valor[:10], "%Y-%m-%d").date()
    except Exception as exc:
        raise ValueError("Data prevista inválida. Use o formato AAAA-MM-DD.") from exc


def _timestamp_ou_none(valor):
    if not valor:
        return None
    try:
        return datetime.fromisoformat(str(valor).replace("Z", "+00:00"))
    except Exception:
        return None


def _iso(valor):
    return valor.isoformat() if valor is not None else None


def _ticket_timestamp(ticket):
    return str(ticket.get("updatedAt") or ticket.get("createdAt") or "")


def _normalizar_status_chamado(status):
    status = str(status or "").strip().lower()
    mapa = {
        "": "queue",
        "pending": "queue",
        "approval": "awaiting_manager",
        "validation": "manager_validation",
        "completed": "done",
        "concluded": "done",
    }
    return mapa.get(status, status)


def _linha_para_ticket(row, historico=None):
    return {
        "id": int(row["id"]),
        "number": int(row["numero"]),
        "title": row["titulo"] or "",
        "type": row["tipo"] or "",
        "project": row["setor"] or "",
        "description": row["descricao"] or "",
        "objective": row["objetivo"] or "",
        "formula": row["formula"] or "",
        "demandKind": row["tipo_demanda"] or "externa",
        "requesterId": int(row["solicitante_id"]) if row["solicitante_id"] is not None else None,
        "requesterName": row["solicitante_nome"] or "",
        "requesterContact": row["solicitante_contato"] or "",
        "requesterEmail": row["solicitante_email"] or "",
        "status": _normalizar_status_chamado(row["status"]),
        "priority": row["prioridade"] or "Média",
        "assignedTo": row["responsavel"] or "",
        "assignedToId": int(row["responsavel_id"]) if row["responsavel_id"] is not None else None,
        "plannedStart": str(row["inicio_previsto"]) if row["inicio_previsto"] else "",
        "plannedEnd": str(row["fim_previsto"]) if row["fim_previsto"] else "",
        "attachments": _json_lista(row["anexos"]),
        "comments": _json_lista(row["comentarios"]),
        "checklist": _json_lista(row["checklist"]),
        "tags": _json_lista(row["tags"]),
        "boardOrder": row["ordem_kanban"],
        "delayReason": row["motivo_atraso"] or "",
        "delayReasonUpdatedAt": _iso(row["motivo_atraso_atualizado_em"]),
        "returnPriority": row["prioridade_retorno"] or "",
        "createdAt": _iso(row["criado_em"]),
        "updatedAt": _iso(row["atualizado_em"]),
        "history": historico or [],
    }


def _ler_historico_chamados(conn):
    rows = conn.execute(text("""
        SELECT chamado_id, usuario_id, usuario_nome, acao, detalhe, criado_em
        FROM public.historico_chamados
        ORDER BY criado_em ASC, id ASC
    """)).mappings().all()

    por_chamado = {}
    for row in rows:
        por_chamado.setdefault(int(row["chamado_id"]), []).append({
            "at": _iso(row["criado_em"]),
            "by": row["usuario_nome"] or "",
            "action": row["acao"] or "",
            "detail": row["detalhe"] or "",
        })
    return por_chamado


def _ler_gestores_chamados(conn):
    rows = conn.execute(text("""
        SELECT id, nome, email, tipo_aprovacao, ativo
        FROM public.gestores_chamados
        ORDER BY nome, id
    """)).mappings().all()
    return [{
        "id": int(r["id"]),
        "name": r["nome"],
        "email": r["email"],
        "approvalType": r["tipo_aprovacao"] or "both",
        "active": bool(r["ativo"]),
    } for r in rows]


def _montar_store_chamados(conn):
    historico = _ler_historico_chamados(conn)
    rows = conn.execute(text("""
        SELECT
            id, numero, titulo, tipo, setor, descricao, objetivo, formula,
            tipo_demanda, solicitante_id, solicitante_nome, solicitante_contato,
            solicitante_email, status, prioridade, responsavel, responsavel_id,
            inicio_previsto, fim_previsto, anexos, comentarios, checklist, tags,
            ordem_kanban, motivo_atraso, motivo_atraso_atualizado_em,
            prioridade_retorno, criado_em, atualizado_em
        FROM public.chamados
        ORDER BY atualizado_em DESC, id DESC
    """)).mappings().all()

    tickets = [
        _linha_para_ticket(row, historico.get(int(row["id"]), []))
        for row in rows
    ]

    ultima = max((r["atualizado_em"] for r in rows), default=None)
    revision = int(ultima.timestamp() * 1000) if ultima else 0

    return {
        "managers": _ler_gestores_chamados(conn),
        "tickets": tickets,
        "revision": revision,
        "updatedAt": _iso(ultima),
    }


def ler_chamados_store():
    try:
        with engine.begin() as conn:
            # Normalização definitiva de valores legados gerados por versões
            # antigas do frontend. Isso elimina o status literal "pending".
            conn.execute(text("""
                UPDATE public.chamados
                SET status = CASE
                    WHEN LOWER(status) = 'pending' THEN 'queue'
                    WHEN LOWER(status) = 'approval' THEN 'awaiting_manager'
                    WHEN LOWER(status) = 'validation' THEN 'manager_validation'
                    WHEN LOWER(status) IN ('completed', 'concluded') THEN 'done'
                    ELSE status
                END
                WHERE LOWER(status) IN (
                    'pending', 'approval', 'validation', 'completed', 'concluded'
                )
            """))
            return _montar_store_chamados(conn)
    except Exception as e:
        log(f"Falha ao ler chamados no Neon: {e}", "ERRO")
        raise


def _numero_para_novo_chamado(conn, ticket_id, numero_solicitado, novo=False):
    if novo:
        # Mesmo lock para criacao normal e importacao: nao reservar MAX(numero) em paralelo.
        conn.execute(text("SELECT pg_advisory_xact_lock(742013, 2)"))
    try:
        numero = int(numero_solicitado)
    except Exception:
        numero = None

    if numero is not None:
        dono = conn.execute(text("""
            SELECT id FROM public.chamados WHERE numero = :numero LIMIT 1
        """), {"numero": numero}).scalar()
        if dono is None or int(dono) == int(ticket_id):
            return numero

    return int(conn.execute(text("""
        SELECT GREATEST(COALESCE(MAX(numero), 1053) + 1, 1054)
        FROM public.chamados
    """)).scalar_one())



ANEXO_MAX_BYTES = 10 * 1024 * 1024
ANEXOS_MAX_POR_ENVIO = 5
RESPONSAVEIS_BI_IDS = (1, 36)


def _usuario_portal_atual(conn, usuario_sessao):
    if not isinstance(usuario_sessao, dict):
        return None
    for chave in ("id", "usuario_id", "user_id"):
        usuario = _usuario_ativo_por_id(conn, usuario_sessao.get(chave))
        if usuario:
            return usuario
    return _usuario_ativo_por_email(conn, usuario_sessao.get("email"))


def _usuario_portal_e_admin(conn, usuario_sessao):
    usuario = _usuario_portal_atual(conn, usuario_sessao)
    if not usuario:
        return False
    perfil = str(usuario.get("perfil") or "").strip().lower()
    role = str(usuario.get("role") or "").strip().lower()
    return perfil == "admin" or role == "admin"


def _usuario_ativo_por_id(conn, usuario_id):
    try:
        usuario_id = int(usuario_id)
    except Exception:
        return None
    return conn.execute(text("""
        SELECT id, nome, email, perfil, role
        FROM public.usuarios
        WHERE id = :id AND ativo = TRUE
        LIMIT 1
    """), {"id": usuario_id}).mappings().first()


def _usuario_ativo_por_email(conn, email):
    email = str(email or "").strip().lower()
    if not email:
        return None
    return conn.execute(text("""
        SELECT id, nome, email, perfil, role
        FROM public.usuarios
        WHERE LOWER(email) = :email AND ativo = TRUE
        LIMIT 1
    """), {"email": email}).mappings().first()


def _usuario_ativo_por_nome(conn, nome):
    nome = str(nome or "").strip()
    if not nome:
        return None
    return conn.execute(text("""
        SELECT id, nome, email, perfil, role
        FROM public.usuarios
        WHERE LOWER(nome) = LOWER(:nome) AND ativo = TRUE
        ORDER BY id
        LIMIT 1
    """), {"nome": nome}).mappings().first()


def _resolver_datas_planejamento_chamado(ticket, existente, pode_planejar):
    """Resolve datas previstas respeitando permissão do usuário atual.

    - Equipe/admin: pode definir/alterar as datas enviadas no payload.
    - Usuário comum, chamado novo: datas ficam vazias.
    - Usuário comum, chamado existente: preserva exatamente as datas já salvas.
    """
    if pode_planejar:
        inicio = _data_ou_none(ticket.get("plannedStart"))
        fim = _data_ou_none(ticket.get("plannedEnd"))
        if inicio and fim and fim < inicio:
            raise ValueError("A data de fim prevista não pode ser anterior à data de início.")
        return inicio, fim

    if existente:
        return existente.get("inicio_previsto"), existente.get("fim_previsto")

    return None, None


def _validar_lista_anexos(anexos, contexto="anexos"):
    anexos = _json_lista(anexos)
    if len(anexos) > ANEXOS_MAX_POR_ENVIO:
        raise ValueError(
            f"Máximo de {ANEXOS_MAX_POR_ENVIO} anexos por envio."
        )
    for anexo in anexos:
        if not isinstance(anexo, dict):
            continue
        try:
            tamanho = int(anexo.get("size") or 0)
        except Exception:
            tamanho = 0
        if tamanho > ANEXO_MAX_BYTES:
            nome = str(anexo.get("name") or "arquivo")
            raise ValueError(
                f'O anexo "{nome}" excede o limite de 10 MB.'
            )
    return anexos


def _validar_anexos_ticket(ticket):
    _validar_lista_anexos(ticket.get("attachments"), "chamado")
    for comentario in _json_lista(ticket.get("comments")):
        if isinstance(comentario, dict):
            _validar_lista_anexos(comentario.get("attachments"), "comentário")


def _salvar_historico_ticket(conn, chamado_id, history):
    conn.execute(text(
        "DELETE FROM public.historico_chamados WHERE chamado_id = :chamado_id"
    ), {"chamado_id": chamado_id})

    for item in _json_lista(history):
        if not isinstance(item, dict):
            continue
        acao = str(item.get("action") or "Atualização")[:250]
        usuario_nome = str(item.get("by") or "")[:200] or None
        usuario = _usuario_ativo_por_nome(conn, usuario_nome)
        conn.execute(text("""
            INSERT INTO public.historico_chamados
                (chamado_id, usuario_id, usuario_nome, acao, detalhe, criado_em)
            VALUES
                (:chamado_id, :usuario_id, :usuario_nome, :acao, :detalhe,
                 COALESCE(:criado_em, NOW()))
        """), {
            "chamado_id": chamado_id,
            "usuario_id": int(usuario["id"]) if usuario else None,
            "usuario_nome": usuario["nome"] if usuario else usuario_nome,
            "acao": acao,
            "detalhe": str(item.get("detail") or "") or None,
            "criado_em": _timestamp_ou_none(item.get("at")),
        })


def _upsert_ticket(conn, ticket, usuario_sessao=None):
    if not isinstance(ticket, dict):
        return False

    try:
        ticket_id = int(ticket.get("id"))
    except Exception:
        return False

    existente = conn.execute(text("""
        SELECT id, atualizado_em
        FROM public.chamados
        WHERE id = :id
        FOR UPDATE
    """), {"id": ticket_id}).mappings().first()

    incoming_updated = _timestamp_ou_none(ticket.get("updatedAt"))
    if existente is not None and incoming_updated is not None:
        db_updated = existente["atualizado_em"]
        if db_updated is not None and incoming_updated < db_updated - timedelta(seconds=2):
            return False

    numero = _numero_para_novo_chamado(conn, ticket_id, ticket.get("number"), novo=existente is None)
    titulo = str(ticket.get("title") or "").strip() or f"Chamado #{numero}"
    descricao = str(ticket.get("description") or "").strip() or "Sem descrição."
    criado_em = _timestamp_ou_none(ticket.get("createdAt"))
    _validar_anexos_ticket(ticket)

    # Solicitante:
    # - usuário comum: sempre ele próprio ao abrir; não pode trocar depois;
    # - admin: pode abrir em nome de qualquer usuário ativo e também trocar
    #   o solicitante de um chamado existente.
    existente = conn.execute(text("""
        SELECT
            solicitante_id,
            solicitante_nome,
            solicitante_email,
            inicio_previsto,
            fim_previsto,
            anexos
        FROM public.chamados
        WHERE id = :id
        LIMIT 1
    """), {"id": ticket_id}).mappings().first()

    usuario_atual = _usuario_portal_atual(conn, usuario_sessao)
    admin_atual = _usuario_portal_e_admin(conn, usuario_sessao)
    solicitante = None

    if admin_atual:
        solicitante = _usuario_ativo_por_id(conn, ticket.get("requesterId"))
        if solicitante is None:
            solicitante = _usuario_ativo_por_email(conn, ticket.get("requesterEmail"))
        if solicitante is None:
            solicitante = _usuario_ativo_por_nome(conn, ticket.get("requesterName"))
        if solicitante is None:
            raise ValueError("Solicitante inválido. Selecione um usuário ativo do Portal.")
    elif existente:
        solicitante = _usuario_ativo_por_id(conn, existente["solicitante_id"])
        if solicitante is None:
            solicitante = _usuario_ativo_por_email(conn, existente["solicitante_email"])
        if solicitante is None:
            solicitante = usuario_atual
    else:
        solicitante = usuario_atual

    if solicitante is None:
        raise ValueError("Não foi possível identificar o solicitante do chamado.")

    # Responsável = analista/desenvolvedor BI.
    # para chamados antigos que ainda não possuíam responsavel_id.
    responsavel_usuario = _usuario_ativo_por_id(conn, ticket.get("assignedToId"))
    if responsavel_usuario is None:
        responsavel_usuario = _usuario_ativo_por_nome(conn, ticket.get("assignedTo"))
    if responsavel_usuario and int(responsavel_usuario["id"]) not in RESPONSAVEIS_BI_IDS:
        raise ValueError("Responsável inválido. Selecione Vitor Souza ou Anderson Jr.")

    prioridade = str(ticket.get("priority") or "Média").strip() or "Média"
    prioridades_validas = {"Baixa", "Média", "Alta", "Urgente"}
    if prioridade not in prioridades_validas:
        raise ValueError("Prioridade inválida. Use Baixa, Média, Alta ou Urgente.")

    # Planejamento de datas:
    # - prioridade pode ser informada pelo solicitante;
    # - datas previstas são controladas pela equipe administrativa/BI;
    # - usuário comum não consegue inserir ou sobrescrever datas via payload;
    # - ao salvar comentários/checklist, datas já definidas são preservadas.
    inicio_previsto, fim_previsto = _resolver_datas_planejamento_chamado(
        ticket,
        existente,
        admin_atual,
    )

    params = {
        "id": ticket_id,
        "numero": numero,
        "titulo": titulo[:250],
        "tipo": str(ticket.get("type") or "")[:100] or None,
        "setor": str(ticket.get("project") or "")[:150] or None,
        "descricao": descricao,
        "objetivo": str(ticket.get("objective") or "") or None,
        "formula": str(ticket.get("formula") or "") or None,
        "tipo_demanda": str(ticket.get("demandKind") or "externa")[:30],
        "solicitante_id": int(solicitante["id"]) if solicitante else None,
        "solicitante_nome": solicitante["nome"] if solicitante else (str(ticket.get("requesterName") or "")[:200] or None),
        "solicitante_contato": str(ticket.get("requesterContact") or "")[:200] or None,
        "solicitante_email": solicitante["email"] if solicitante else (str(ticket.get("requesterEmail") or "")[:250] or None),
        "status": _normalizar_status_chamado(ticket.get("status"))[:50],
        "prioridade": prioridade,
        "responsavel": responsavel_usuario["nome"] if responsavel_usuario else (str(ticket.get("assignedTo") or "")[:200] or None),
        "responsavel_id": int(responsavel_usuario["id"]) if responsavel_usuario else None,
        "inicio_previsto": inicio_previsto,
        "fim_previsto": fim_previsto,
        "anexos": json.dumps(_validar_lista_anexos(forms_drive.merge_managed(
            existente.get("anexos") if existente else [], ticket.get("attachments"))), ensure_ascii=False),
        "comentarios": json.dumps(_json_lista(ticket.get("comments")), ensure_ascii=False),
        "checklist": json.dumps(_json_lista(ticket.get("checklist")), ensure_ascii=False),
        "tags": json.dumps(_json_lista(ticket.get("tags")), ensure_ascii=False),
        "ordem_kanban": int(ticket.get("boardOrder")) if str(ticket.get("boardOrder") or "").lstrip("-").isdigit() else None,
        "motivo_atraso": str(ticket.get("delayReason") or "") or None,
        "motivo_atraso_atualizado_em": _timestamp_ou_none(ticket.get("delayReasonUpdatedAt")),
        "prioridade_retorno": str(ticket.get("returnPriority") or "")[:30] or None,
        "criado_em": criado_em,
    }

    conn.execute(text("""
        INSERT INTO public.chamados (
            id, numero, titulo, tipo, setor, descricao, objetivo, formula,
            tipo_demanda, solicitante_id, solicitante_nome, solicitante_contato,
            solicitante_email, status, prioridade, responsavel, responsavel_id,
            inicio_previsto, fim_previsto, anexos, comentarios, checklist, tags,
            ordem_kanban, motivo_atraso, motivo_atraso_atualizado_em,
            prioridade_retorno, criado_em
        ) VALUES (
            :id, :numero, :titulo, :tipo, :setor, :descricao, :objetivo, :formula,
            :tipo_demanda, :solicitante_id, :solicitante_nome, :solicitante_contato,
            :solicitante_email, :status, :prioridade, :responsavel, :responsavel_id,
            :inicio_previsto, :fim_previsto, CAST(:anexos AS jsonb),
            CAST(:comentarios AS jsonb), CAST(:checklist AS jsonb), CAST(:tags AS jsonb),
            :ordem_kanban, :motivo_atraso, :motivo_atraso_atualizado_em,
            :prioridade_retorno, COALESCE(:criado_em, NOW())
        )
        ON CONFLICT (id) DO UPDATE SET
            numero = EXCLUDED.numero,
            titulo = EXCLUDED.titulo,
            tipo = EXCLUDED.tipo,
            setor = EXCLUDED.setor,
            descricao = EXCLUDED.descricao,
            objetivo = EXCLUDED.objetivo,
            formula = EXCLUDED.formula,
            tipo_demanda = EXCLUDED.tipo_demanda,
            solicitante_id = EXCLUDED.solicitante_id,
            solicitante_nome = EXCLUDED.solicitante_nome,
            solicitante_contato = EXCLUDED.solicitante_contato,
            solicitante_email = EXCLUDED.solicitante_email,
            status = EXCLUDED.status,
            prioridade = EXCLUDED.prioridade,
            responsavel = EXCLUDED.responsavel,
            responsavel_id = EXCLUDED.responsavel_id,
            inicio_previsto = EXCLUDED.inicio_previsto,
            fim_previsto = EXCLUDED.fim_previsto,
            anexos = EXCLUDED.anexos,
            comentarios = EXCLUDED.comentarios,
            checklist = EXCLUDED.checklist,
            tags = EXCLUDED.tags,
            ordem_kanban = EXCLUDED.ordem_kanban,
            motivo_atraso = EXCLUDED.motivo_atraso,
            motivo_atraso_atualizado_em = EXCLUDED.motivo_atraso_atualizado_em,
            prioridade_retorno = EXCLUDED.prioridade_retorno
    """), params)

    _salvar_historico_ticket(conn, ticket_id, ticket.get("history"))
    return True


def _salvar_gestores(conn, managers):
    if not isinstance(managers, list):
        return
    for manager in managers:
        if not isinstance(manager, dict):
            continue
        email = str(manager.get("email") or "").strip().lower()
        nome = str(manager.get("name") or "").strip()
        if not email or not nome:
            continue
        conn.execute(text("""
            INSERT INTO public.gestores_chamados
                (nome, email, tipo_aprovacao, ativo)
            VALUES
                (:nome, :email, :tipo_aprovacao, :ativo)
            ON CONFLICT ((LOWER(email))) DO UPDATE SET
                nome = EXCLUDED.nome,
                tipo_aprovacao = EXCLUDED.tipo_aprovacao,
                ativo = EXCLUDED.ativo,
                atualizado_em = NOW()
        """), {
            "nome": nome[:200],
            "email": email[:250],
            "tipo_aprovacao": str(manager.get("approvalType") or "both")[:30],
            "ativo": bool(manager.get("active", True)),
        })


def salvar_chamados_store(data, somente_gestores_se_vazio=False, usuario_sessao=None):
    data = data if isinstance(data, dict) else {}
    incoming_tickets = data.get("tickets") if isinstance(data.get("tickets"), list) else []
    incoming_managers = data.get("managers") if isinstance(data.get("managers"), list) else []

    with CHAMADOS_LOCK:
        with engine.begin() as conn:
            for ticket in incoming_tickets:
                _upsert_ticket(conn, ticket, usuario_sessao)

            if incoming_managers:
                if not somente_gestores_se_vazio:
                    _salvar_gestores(conn, incoming_managers)
                else:
                    total = conn.execute(text(
                        "SELECT COUNT(*) FROM public.gestores_chamados"
                    )).scalar_one()
                    if int(total or 0) == 0:
                        _salvar_gestores(conn, incoming_managers)

            return _montar_store_chamados(conn)


def mesclar_chamados(server_tickets, incoming_tickets):
    """Compatibilidade com o frontend legado; a decisão final ocorre no Neon."""
    merged = {}
    for item in server_tickets or []:
        if isinstance(item, dict) and item.get("id") is not None:
            merged[str(item["id"])] = item
    for item in incoming_tickets or []:
        if not isinstance(item, dict) or item.get("id") is None:
            continue
        key = str(item["id"])
        anterior = merged.get(key)
        if anterior is None or _ticket_timestamp(item) >= _ticket_timestamp(anterior):
            merged[key] = item
    return list(merged.values())


