# ESTADO
# =============================================================================

def estado_padrao():
    cfg = load_config()
    data = {
        "api": {
            "status": "online",
            "url": cfg.get("api", {}).get("public_url", "http://192.168.1.193:5000"),
            "inicio": agora(),
        },
        "execucao": {
            "status": "aguardando",
            "modo": None,
            "inicio": None,
            "fim": None,
            "etapa_atual": None,
            "concluidos": [],
            "fila": [],
            "erro": None,
        },
        "relatorios": {},
        "historico": [],
    }

    for r in get_robos():
        data["relatorios"][r["id"]] = {
            "id": r["id"],
            "modulo": r.get("modulo"),
            "nome": r["nome"],
            "arquivo": r["script"],
            "status": "Aguardando",
            "ultima": None,
            "duracao": None,
            "periodo": None,
            "ultima_data_arquivo": None,
            "arquivo_mais_recente": None,
            "total_arquivos": 0,
            "erro": None,
        }

    return data


def carregar_estado(scan_pastas=False):
    if STATUS_FILE.exists():
        try:
            data = json.loads(STATUS_FILE.read_text(encoding="utf-8"))
        except Exception:
            data = estado_padrao()
    else:
        data = estado_padrao()

    padrao = estado_padrao()

    data.setdefault("api", padrao["api"])
    data.setdefault("execucao", padrao["execucao"])
    data.setdefault("relatorios", {})
    data.setdefault("historico", [])

    exec_rodando = data["execucao"].get("status") == "executando"

    for robo in get_robos():
        rid = robo["id"]
        atual = data["relatorios"].get(rid, padrao["relatorios"][rid])

        if scan_pastas and not exec_rodando:
            pasta = status_pasta_robo(robo)
            atual["ultima"] = pasta["ultima"] or atual.get("ultima")
            atual["ultima_data_arquivo"] = pasta["ultima_data_arquivo"]
            atual["arquivo_mais_recente"] = pasta["arquivo_mais_recente"]
            atual["total_arquivos"] = pasta["total_arquivos"]

            if pasta["ultima_data_arquivo"]:
                atual["periodo"] = f"Dados até {pasta['ultima_data_arquivo']}"

            if atual.get("status") in (None, "Aguardando") and pasta["ultima"]:
                atual["status"] = "Sucesso"

        atual["id"] = rid
        atual["modulo"] = robo.get("modulo")
        atual["nome"] = robo["nome"]
        atual["arquivo"] = robo["script"]

        data["relatorios"][rid] = atual

    return data


def atualizar_relatorio(rid, **kwargs):
    data = carregar_estado(scan_pastas=False)

    if rid in data["relatorios"]:
        data["relatorios"][rid].update(kwargs)

    salvar_status(data)
    return data


def set_execucao(**kwargs):
    data = carregar_estado(scan_pastas=False)
    data["execucao"].update(kwargs)
    salvar_status(data)
    return data


def marcar_fila(ids, periodo):
    info = periodo_datas(periodo)
    data = carregar_estado(scan_pastas=False)

    for rid in ids:
        if rid in data["relatorios"]:
            data["relatorios"][rid].update({
                "status": "Em andamento",
                "periodo": info["nome"],
                "duracao": None,
                "erro": None,
            })

    salvar_status(data)


def finalizar_status_pastas():
    data = carregar_estado(scan_pastas=True)
    salvar_status(data)


# =============================================================================
# EXECUÇÃO
# =============================================================================

def duracao(seg):
    return time.strftime("%H:%M:%S", time.gmtime(max(0, seg)))


def montar_comando(caminho, rid, periodo, tratamento_modo="incremental"):
    info = periodo_datas(periodo)
    dias = info.get("dias")

    cmd = [sys.executable, "-u", str(caminho)]

    # Tratamentos:
    # - incremental = padrão, lê somente arquivos novos/alterados;
    # - completo = força releitura de todo o histórico.
    tratamentos_com_modo = {
        "tratamento_logistica",
        "tratamento_pcp",
        "tratamento_comercial",
        "tratamento_suprimentos",
        "tratamento_indice_zootecnico",
    }

    if (
        rid in tratamentos_com_modo
        and str(tratamento_modo).lower() == "completo"
    ):
        cmd.append("--completo")

    robos_logistica_com_periodo = {
        "frete", "controle_frete", "devolucoes",
        "ocorrencia_viagens_custo", "faturamento_cfop",
    }
    robos_pcp_incrementais_com_modo = {
        "pcp_devolucao",
        "pcp_diario_industria",
        "pcp_diario_industria_avenova_turnos",
        "pcp_movimento_geral",
        "pcp_relatorio_condenacoes",
    }
    robos_pcp_incrementais_dias_direto = {"pcp_estoque_transacao"}
    robos_comercial_com_periodo = {
        "comercial_faturamento_cfop",
    }
    robos_suprimentos_com_periodo = {
        "suprimentos_contas_pagas",
        "suprimentos_ordens_compras",
        "suprimentos_solicitacoes_requisitante",
        "suprimentos_titulos_agrupados",
        "suprimentos_notas_fiscais_item",
    }

    robos_suprimentos_datas_diretas = {
        "suprimentos_relacao_oc_nf",
    }
    robos_indice_zootecnico_com_periodo = {
        "indice_zootecnico_base_dinamica",
        "indice_zootecnico_mortalidade_peso_lotes_abertos",
        "indice_zootecnico_mortalidade_peso_lotes_fechados",
    }
    robos_indice_zootecnico_sem_pausa = {
        "indice_zootecnico_mortalidade_peso_lotes_abertos",
        "indice_zootecnico_mortalidade_peso_lotes_fechados",
    }

    # No período personalizado, os robôs recebem as datas também por argumentos.
    # Além disso, rodar_robo sempre envia AGROSYS_DATA_INICIO e AGROSYS_DATA_FIM
    # no ambiente, permitindo que scripts novos usem as datas sem depender do argparse.
    if info.get("manual"):
        if (
            rid in robos_logistica_com_periodo
            or rid in robos_pcp_incrementais_com_modo
            or rid in robos_comercial_com_periodo
            or rid in robos_suprimentos_com_periodo
            or rid in robos_indice_zootecnico_com_periodo
        ):
            cmd += [
                "--modo", "periodo",
                "--inicio", info["data_inicio"],
                "--fim", info["data_fim"],
            ]
        elif rid in robos_suprimentos_datas_diretas:
            cmd += [
                "--inicio", info["data_inicio"],
                "--fim", info["data_fim"],
            ]
        elif rid in robos_pcp_incrementais_dias_direto:
            cmd += [
                "--inicio", info["data_inicio"],
                "--fim", info["data_fim"],
            ]

        if rid in robos_indice_zootecnico_sem_pausa:
            cmd.append("--sem-pausa")
        if rid == "tratamento_indice_zootecnico":
            cmd.append("--sem-pausa")
        return cmd

    if dias is not None:
        dias = max(int(dias), 1)
        if rid in robos_logistica_com_periodo:
            cmd += ["--modo", "dias", "--dias", str(dias)]
        elif rid in robos_comercial_com_periodo:
            cmd += ["--modo", "dias", "--dias", str(dias)]
        elif rid in robos_suprimentos_com_periodo:
            cmd += [
                "--modo", "periodo",
                "--inicio", info["data_inicio"],
                "--fim", info["data_fim"],
            ]
        elif rid in robos_suprimentos_datas_diretas:
            cmd += [
                "--inicio", info["data_inicio"],
                "--fim", info["data_fim"],
            ]
        elif rid in robos_pcp_incrementais_com_modo:
            cmd += ["--modo", "dias", "--dias", str(dias)]
        elif rid in robos_pcp_incrementais_dias_direto:
            cmd += ["--dias", str(dias)]
        elif rid in robos_indice_zootecnico_com_periodo:
            cmd += ["--modo", "dias", "--dias", str(dias)]

    if rid in robos_indice_zootecnico_sem_pausa:
        cmd.append("--sem-pausa")
    if rid == "tratamento_indice_zootecnico":
        cmd.append("--sem-pausa")

    return cmd


def ler_stdout_em_thread(proc, saida):
    try:
        for linha in iter(proc.stdout.readline, ""):
            if linha:
                saida.put(linha.rstrip())
    except Exception as e:
        saida.put(f"[LEITOR] Erro lendo saída do processo: {e}")


def rodar_robo(robo, periodo, tratamento_modo="incremental"):
    rid = robo["id"]
    caminho_configurado = Path(robo["script"])
    caminho = resolver_caminho_script(robo)
    info = periodo_datas(periodo)
    inicio = time.time()

    set_execucao(etapa_atual=robo["nome"])

    # Garante que só o atual fique Atualizando; os outros da fila ficam Em andamento.
    data = carregar_estado(scan_pastas=False)
    concluidos_ids = set(data.get("execucao", {}).get("concluidos", []) or [])
    concluidos_nomes = set(data.get("execucao", {}).get("concluidos_nomes", []) or [])

    for rid_fila in data["execucao"].get("fila", []):
        if rid_fila in data["relatorios"] and data["relatorios"][rid_fila].get("status") == "Atualizando":
            nome_fila = data["relatorios"][rid_fila].get("nome")
            if rid_fila in concluidos_ids or nome_fila in concluidos_nomes:
                data["relatorios"][rid_fila]["status"] = "Sucesso"
            else:
                data["relatorios"][rid_fila]["status"] = "Em andamento"
    if rid in data["relatorios"]:
        data["relatorios"][rid].update({
            "status": "Atualizando",
            "periodo": info["nome"],
            "erro": None,
            "duracao": None,
        })
    salvar_status(data)

    log("=" * 80)
    log(f"INICIANDO: {robo['nome']}")
    log(f"API CARREGADA DE: {APP_FILE}")
    log(f"VERSÃO DA API: {APP_VERSION}")
    log(f"ARQUIVO CONFIGURADO: {caminho_configurado}")
    log(f"ARQUIVO UTILIZADO: {caminho}")
    log(f"PERÍODO: {info['nome']} | {info['data_inicio']} até {info['data_fim']}")
    log("=" * 80)

    if not caminho.exists():
        erro = f"Arquivo não encontrado: {caminho}"
        atualizar_relatorio(rid, status="Erro", erro=erro, duracao="00:00:00")
        log(erro, "ERRO")
        return False, erro, "00:00:00"

    env = os.environ.copy()
    env["PYTHONUNBUFFERED"] = "1"
    env["AGROSYS_PERIODO"] = info["codigo"]
    env["AGROSYS_DATA_INICIO"] = info["data_inicio"]
    env["AGROSYS_DATA_FIM"] = info["data_fim"]

    cmd = montar_comando(caminho, rid, periodo, tratamento_modo=tratamento_modo)
    nomes_tratamento = {
        "tratamento_logistica": "LOGÍSTICA",
        "tratamento_pcp": "PCP",
        "tratamento_comercial": "COMERCIAL",
        "tratamento_suprimentos": "SUPRIMENTOS",
        "tratamento_indice_zootecnico": "ÍNDICE ZOOTÉCNICO",
    }

    if rid in nomes_tratamento:
        log(
            f"MODO DE TRATAMENTO {nomes_tratamento[rid]}: "
            + (
                "COMPLETO - reprocessar todo o histórico"
                if str(tratamento_modo).lower() == "completo"
                else "INCREMENTAL - somente arquivos novos/alterados"
            )
        )
    log(f"COMANDO: {' '.join(cmd)}")

    try:
        creationflags = 0
        if os.name == "nt":
            # Isola o robô em um novo grupo de processo.
            # Assim, se o script filho terminar, ele não derruba a API/Flask.
            creationflags = subprocess.CREATE_NEW_PROCESS_GROUP

        proc = subprocess.Popen(
            cmd,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            stdin=subprocess.DEVNULL,
            text=True,
            encoding="utf-8",
            errors="replace",
            env=env,
            cwd=str(caminho.parent),
            bufsize=1,
            creationflags=creationflags,
        )
    except Exception as e:
        erro = f"Falha ao iniciar o robô: {e}"
        atualizar_relatorio(rid, status="Erro", erro=erro, duracao="00:00:00")
        log(erro, "ERRO")
        return False, erro, "00:00:00"

    saida = queue.Queue()
    threading.Thread(target=ler_stdout_em_thread, args=(proc, saida), daemon=True).start()

    ultimo_log = time.time()
    while proc.poll() is None:
        recebeu = False

        while True:
            try:
                linha = saida.get_nowait()
            except queue.Empty:
                break

            recebeu = True
            if linha:
                log(linha, "PY")
                ultimo_log = time.time()

        if not recebeu and time.time() - ultimo_log >= 10:
            log(
                f"Aguardando retorno do Agrosys/robô '{robo['nome']}'... "
                f"tempo em execução: {duracao(time.time() - inicio)}",
                "INFO",
            )
            ultimo_log = time.time()

        time.sleep(0.5)

    while True:
        try:
            linha = saida.get_nowait()
        except queue.Empty:
            break
        if linha:
            log(linha, "PY")

    retorno = proc.wait()
    tempo = duracao(time.time() - inicio)

    if retorno == 0:
        atualizar_relatorio(rid, status="Sucesso", ultima=agora(), duracao=tempo, erro=None, periodo=info["nome"])
        log(f"OK: {robo['nome']} finalizado em {tempo}", "OK")
        return True, "Sucesso", tempo

    erro = f"Código de retorno {retorno}"
    atualizar_relatorio(rid, status="Erro", ultima=agora(), duracao=tempo, erro=erro)
    log(erro, "ERRO")
    return False, erro, tempo


def executar_fila(ids, modo, periodo, tratamento_modo="incremental"):
    with EXEC_LOCK:
        data = carregar_estado(scan_pastas=False)

        if data["execucao"].get("status") == "executando":
            log("Já existe execução em andamento. Solicitação ignorada.", "WARN")
            return

        log("NOVA EXECUÇÃO INICIADA PELO PORTAL BI", "INFO")

        data["execucao"] = {
            "status": "executando",
            "modo": modo,
            "inicio": agora(),
            "fim": None,
            "etapa_atual": None,
            "concluidos": [],
            "concluidos_nomes": [],
            "fila": ids,
            "total": len(ids),
            "concluidos_qtd": 0,
            "percentual": 0,
            "erro": None,
            "periodo": periodo_datas(periodo),
        }
        salvar_status(data)

        marcar_fila(ids, periodo)

        robos = {r["id"]: r for r in get_robos()}
        inicio_total = time.time()

        log(f"MODO: {modo}")
        log(f"PERÍODO: {periodo_datas(periodo)['nome']}")
        log(f"FILA: {len(ids)} relatório(s)")
        log("-" * 80)

        for rid in ids:
            robo = robos.get(rid)
            if not robo:
                continue

            ok, msg, tempo = rodar_robo(robo, periodo, tratamento_modo=tratamento_modo)

            data = carregar_estado(scan_pastas=False)

            if ok:
                # Garante que o status do relatório finalizado acompanhe o terminal.
                # Antes alguns itens ficavam presos em "Em andamento" porque o estado
                # era salvo novamente logo após o retorno do robô.
                if rid in data.get("relatorios", {}):
                    data["relatorios"][rid]["status"] = "Sucesso"
                    data["relatorios"][rid]["ultima"] = agora()
                    data["relatorios"][rid]["duracao"] = tempo
                    data["relatorios"][rid]["erro"] = None
                    data["relatorios"][rid]["periodo"] = periodo_datas(periodo)["nome"]

                # Guarda por ID e por nome para ficar compatível com qualquer frontend.
                concluidos = data["execucao"].setdefault("concluidos", [])
                if rid not in concluidos:
                    concluidos.append(rid)

                concluidos_nomes = data["execucao"].setdefault("concluidos_nomes", [])
                if robo["nome"] not in concluidos_nomes:
                    concluidos_nomes.append(robo["nome"])

                # Campos extras para a barra/progresso.
                total_fila = len(data["execucao"].get("fila", []) or ids)
                data["execucao"]["total"] = total_fila
                data["execucao"]["concluidos_qtd"] = len(concluidos)
                data["execucao"]["percentual"] = round((len(concluidos) / total_fila) * 100) if total_fila else 100

                salvar_status(data)
            else:
                data["execucao"].update({
                    "status": "erro",
                    "fim": agora(),
                    "etapa_atual": robo["nome"],
                    "erro": msg,
                })
                data["historico"].insert(0, {
                    "data": agora(),
                    "modo": modo,
                    "nome": robo["nome"],
                    "status": "Erro",
                    "duracao": tempo,
                    "erro": msg,
                })
                data["historico"] = data["historico"][:100]
                salvar_status(data)
                log(f"EXECUÇÃO INTERROMPIDA: {robo['nome']}", "ERRO")
                return

        total = duracao(time.time() - inicio_total)

        finalizar_status_pastas()

        data = carregar_estado(scan_pastas=False)
        data["execucao"].update({
            "status": "concluido",
            "fim": agora(),
            "etapa_atual": None,
            "fila": [],
            "concluidos_qtd": len(ids),
            "total": len(ids),
            "percentual": 100,
            "erro": None,
        })
        data["historico"].insert(0, {
            "data": agora(),
            "modo": modo,
            "nome": "Atualização concluída",
            "status": "Sucesso",
            "duracao": total,
            "erro": None,
        })
        data["historico"] = data["historico"][:100]
        salvar_status(data)

        log("=" * 80)
        log(f"EXECUÇÃO CONCLUÍDA COM SUCESSO EM {total}", "OK")
        log("=" * 80)


def executar_fila_segura(ids, modo, periodo, tratamento_modo="incremental"):
    try:
        executar_fila(ids, modo, periodo, tratamento_modo=tratamento_modo)
    except Exception as e:
        # Nunca deixa uma falha na fila derrubar a API.
        log(f"ERRO GERAL NA FILA: {e}", "ERRO")
        try:
            data = carregar_estado(scan_pastas=False)
            data["execucao"].update({
                "status": "erro",
                "fim": agora(),
                "erro": str(e),
            })
            salvar_status(data)
        except Exception as e2:
            log(f"Falha ao salvar erro geral: {e2}", "ERRO")


def iniciar_execucao(ids, modo, periodo, tratamento_modo="incremental"):
    global EXEC_THREAD
    # Não usar daemon=True. A API precisa continuar viva após o robô/tratamento finalizar.
    EXEC_THREAD = threading.Thread(target=executar_fila_segura, args=(ids, modo, periodo, tratamento_modo), daemon=False)
    EXEC_THREAD.start()



